// The static world of the career mode: which clubs exist and which real players belong to which club.
// It is plain data (generated by scripts/data from sourced squads), so the engine can run on a tiny made-up world in tests.

import { registerPlayers, type Pos } from '../players';

export type Line = 'GK' | 'DF' | 'MF' | 'FW';

export interface WorldClub {
  id: string;
  name: string;
  country: string;
  league: 1 | 2;
  /** shirt colours (hex), or null to derive them from the name */
  colors: [string, string] | null;
}

export interface WorldPlayer {
  id: string;
  name: string;
  nat: string;
  pos: Pos;
  /** rating at the start of the career, 40..90 */
  ovr: number;
  /** age at the start, only when a source gave a birth date */
  age: number | null;
  club: string;
  no: number | null;
}

export interface World {
  clubs: WorldClub[];
  players: WorldPlayer[];
}

export interface IndexedWorld extends World {
  club: (id: string) => WorldClub;
  player: (id: string) => WorldPlayer;
  has: (id: string) => boolean;
  byClub: ReadonlyMap<string, readonly WorldPlayer[]>;
  /** the keeper rating that stops the average share of shots in this league (see GK_PIVOT_ABOVE_MEAN) */
  gkPivot: number;
}

export function lineOf(pos: Pos): Line {
  switch (pos) {
    case 'GK': return 'GK';
    case 'LB': case 'CB': case 'RB': return 'DF';
    case 'CDM': case 'CM': case 'CAM': return 'MF';
    default: return 'FW';
  }
}

/**
 * Keeper rating that stops the average share of shots in a career league: the mean keeper of the world plus this. A career league is not
 * a pool of drafted stars (its keepers average 64, the draft game's 87), so the keeper curve is centred on its own level. The offset keeps
 * goals per match where they were before the curve was steepened (2.60 on the real data, six seeds, 14 matchdays); `npm run check:balance` watches it.
 */
export const GK_PIVOT_ABOVE_MEAN = 5.5;

/** Index a world and make its players known to the match engine. Safe to call again with the same data. */
export function indexWorld(w: World): IndexedWorld {
  const clubs = new Map(w.clubs.map((c) => [c.id, c]));
  const players = new Map(w.players.map((p) => [p.id, p]));
  const byClub = new Map<string, WorldPlayer[]>();
  for (const p of w.players) {
    if (!clubs.has(p.club)) throw new Error(`Player ${p.id} belongs to unknown club ${p.club}`);
    (byClub.get(p.club) ?? byClub.set(p.club, []).get(p.club)!).push(p);
  }
  const keepers = w.players.filter((p) => p.pos === 'GK').map((p) => p.ovr);
  const gkPivot = keepers.length ? Math.round((keepers.reduce((a, b) => a + b, 0) / keepers.length + GK_PIVOT_ABOVE_MEAN) * 10) / 10 : 85;
  registerPlayers(w.players.map((p) => ({ id: p.id, name: p.name, nat: p.nat, pos: p.pos, ovr: p.ovr, era: 'M' as const })));
  return {
    ...w,
    club: (id) => { const c = clubs.get(id); if (!c) throw new Error(`Unknown club ${id}`); return c; },
    player: (id) => { const p = players.get(id); if (!p) throw new Error(`Unknown career player ${id}`); return p; },
    has: (id) => players.has(id),
    byClub,
    gkPivot,
  };
}

/* ───────────── generated badges (never a real crest) ───────────── */

export type BadgeShape = 'shield' | 'round' | 'pennant' | 'diamond';
export type BadgeMark = 'initial' | 'stripes' | 'star' | 'bar';
export interface Badge {
  shape: BadgeShape;
  c1: string;
  c2: string;
  mark: BadgeMark;
}
export const BADGE_SHAPES: readonly BadgeShape[] = ['shield', 'round', 'pennant', 'diamond'];
export const BADGE_MARKS: readonly BadgeMark[] = ['initial', 'stripes', 'star', 'bar'];
/** A small palette so any pair looks intentional; players may also type their own hex colour. */
export const BADGE_COLORS = ['#c8102e', '#ffffff', '#0b3d91', '#111111', '#0e7c3a', '#f2b705', '#7a0f2e', '#1fa2d6', '#ff6a13', '#6a2c91', '#8a8d91', '#e8e1c8'] as const;
export const HEX = /^#[0-9a-fA-F]{6}$/;

function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function defaultBadge(name: string, colors?: [string, string] | null): Badge {
  const h = hash(name);
  const c1 = colors?.[0] ?? BADGE_COLORS[h % BADGE_COLORS.length]!;
  let c2 = colors?.[1] ?? BADGE_COLORS[(h >>> 4) % BADGE_COLORS.length]!;
  if (c2 === c1) c2 = c1 === '#ffffff' ? '#111111' : '#ffffff';
  return { shape: BADGE_SHAPES[(h >>> 8) % BADGE_SHAPES.length]!, c1, c2, mark: BADGE_MARKS[(h >>> 12) % BADGE_MARKS.length]! };
}

export function validBadge(b: unknown): b is Badge {
  if (!b || typeof b !== 'object') return false;
  const x = b as Record<string, unknown>;
  return BADGE_SHAPES.includes(x.shape as BadgeShape) && BADGE_MARKS.includes(x.mark as BadgeMark)
    && typeof x.c1 === 'string' && HEX.test(x.c1) && typeof x.c2 === 'string' && HEX.test(x.c2);
}
